using System; using System.Data.SqlClient; namespace PlacementDashboard.Admin { public partial class EditStudent : System.Web.UI.Page { protected void Page_Load(object sender,EventArgs e) { if(!IsPostBack && Request.QueryString["id"]!=null) { int id=int.Parse(Request.QueryString["id"]); var r=PlacementDashboard.DBConnection.GetStudents().Select("StudentId="+id)[0]; StudentId.Value=id+""; StudentName.Text=(string)r["StudentName"]; Department.Text=(string)r["Department"]; Company.Text=r["Company"]==DBNull.Value?"":(string)r["Company"]; Package.Text=r["Package"]+""; Status.SelectedValue=(string)r["PlacementStatus"]; } } protected void Update_Click(object sender,EventArgs e) { PlacementDashboard.DBConnection.Execute("UPDATE Students SET StudentName=@n,Department=@d,Company=@c,Package=@p,PlacementStatus=@s WHERE StudentId=@id",new SqlParameter("@n",StudentName.Text),new SqlParameter("@d",Department.Text),new SqlParameter("@c",Company.Text),new SqlParameter("@p",decimal.Parse(Package.Text)),new SqlParameter("@s",Status.SelectedValue),new SqlParameter("@id",int.Parse(StudentId.Value))); Response.Redirect("ViewStudents.aspx"); } } }
